#include <stdio.h>

int main() {
    unsigned int flags = 0;
    flags |= (1u << 3);
    flags |= (1u << 0);
    printf("flags = %u\n", flags);
    flags &= ~(1u << 0);
    printf("after clearing bit 0 = %u\n", flags);
    flags ^= (1u << 5);
    printf("after toggling bit 5 = %u\n", flags);
    printf("bit 3 is %s\n", (flags >> 3) & 1 ? "set" : "clear");
    return 0;
}
